"""Detailed explanations with diagrams: HLD questions, part 6."""
from sd_x_util import X, P, H, AN, KEY, FLOW, SEQ, NOTE, ER, TABLE, CALC, BARS, CODE, UML, STATE

X("tinder-hld",
  P("""**What the system does.** Shows each user a **deck** of nearby profiles matching their preferences, records swipes (~60k per second), and creates a **match** the instant two people have liked each other. Reads are served from **precomputed decks**; the match check must be atomic so a mutual like is never missed or double-created."""),
  AN("A matchmaker with a stack of cards prepared overnight for each client (the deck). When you say 'yes' to someone, the matchmaker checks a little box of people who already said yes to you; if they're in it, both of you get a call."),
  CALC("Sizing", [("Swipes per second", "50e6 * 100 / 86400", "/s"), ("Swipe rows per year (~30 B)", "50e6 * 100 * 365 * 30", "B"), ("Deck cache (200 profile ids × 8 B × 50 M users)", "200 * 8 * 50e6", "B")]),
  SEQ("Asha swipes right on Ravi", ["Asha", "Swipe service", "Swipes (Cassandra)", "Likes-received (Redis)", "Match service", "Notifications"],
      [["Asha", "Swipe service", "right(Ravi)"], ["Swipe service", "Swipes (Cassandra)", "write (asha, ravi, LIKE)", "", "Idempotent: the same swipe twice overwrites the same row."],
       ["Swipe service", "Likes-received (Redis)", "SISMEMBER likes:asha ravi", "", "Did Ravi already like Asha?"], ["Likes-received (Redis)", "Swipe service", "yes", "r"],
       ["Swipe service", "Match service", "create match (asha, ravi)", "", "Unique key on the sorted pair (min, max) so two simultaneous mutual likes create only one match."],
       ["Match service", "Notifications", "notify both + open chat", "a"],
       NOTE(["Asha", "Notifications"], "if Ravi hadn't liked Asha yet: SADD likes:ravi asha so his future right-swipe finds it")]),
  TABLE("Building the deck (offline / periodically)", ["Step", "How"], [["candidates", "geo search (Elasticsearch geo_distance) + age/gender filters"], ["exclude seen", "per-user Bloom filter of already-swiped ids"],
        ["rank", "model: likelihood of mutual interest, activity, freshness"], ["serve", "store the top 200 ids per user in Redis; refill when low"], ["privacy", "distances are rounded/fuzzed; exact location never shown"]]))

X("distributed-tracing-hld",
  P("""**What the system does.** Follows one user request through dozens of microservices and shows a **timeline** of where the time went (a trace made of spans). Every service must pass a **trace context** along; spans are exported asynchronously; and because tracing everything would cost 20 M spans/s, the system **samples**, keeping all errors and slow traces."""),
  AN("A parcel tracking number: every depot that handles the parcel scans it and records arrival and departure times, plus which depot sent it. Later you can line up all scans for one tracking number to see where it sat for two days."),
  CALC("Sizing", [("Spans per second unsampled", "s = 1e6 * 20", "/s"), ("At 5% sampling + all errors (~1%)", "s * 0.06", "/s"), ("Storage per day at 500 B per span", "s * 0.06 * 500 * 86400", "B")]),
  SEQ("Context propagation through 3 services", ["Client", "API (span A)", "Orders (span B)", "Payments (span C)", "Collector"],
      [["Client", "API (span A)", "GET /checkout", "", "No traceparent header → API starts trace 4bf9… and root span A."],
       ["API (span A)", "Orders (span B)", "call + header traceparent: 00-4bf9…-A-01", "", "W3C traceparent = trace id + parent span id + sampled flag."],
       ["Orders (span B)", "Payments (span C)", "call + traceparent: 00-4bf9…-B-01"], ["Payments (span C)", "Collector", "export span C (async, batched)", "a", "Exporting never blocks the request; a full buffer drops spans rather than slowing the app."],
       ["Orders (span B)", "Collector", "export span B", "a"], ["API (span A)", "Collector", "export span A", "a"]]),
  TABLE("The resulting trace (waterfall)", ["Span", "Service", "Starts at", "Duration", "Parent"], [["A", "api GET /checkout", "0 ms", "420 ms", "—"], ["B", "orders.create", "12 ms", "380 ms", "A"],
                                                                                              ["C", "payments.authorize", "40 ms", "310 ms ← slow", "B"]],
        "The waterfall shows at a glance that payments, not orders, is the bottleneck."),
  TABLE("Sampling", ["Type", "Decision made", "Keeps", "Cost"], [["head-based", "at the first service (e.g. 5% random)", "a fair sample, but may miss rare errors", "cheap"],
                                                                ["tail-based", "after the whole trace is collected", "all errors and slow traces + a sample of the rest", "collectors must buffer whole traces"]]))

X("llmserving-hld",
  P("""**What the system does.** A ChatGPT-like product: users send messages, the service builds a prompt (history + optional retrieved documents), runs a large model on **GPUs**, and **streams** tokens back. GPUs are the scarce, expensive resource, so the design is about **keeping GPUs busy** (continuous batching, KV-cache reuse), **admission control** under overload, and safety."""),
  AN("A popular restaurant with a few very expensive chefs (GPUs). Orders are grouped so a chef cooks several dishes at once (batching), common base sauces are pre-made (prompt/KV cache), VIP and regular orders have separate queues, and dishes are served course by course as they're ready (streaming)."),
  CALC("Sizing", [("Requests per second (average)", "r = 50e6 * 10 / 86400", "/s"), ("Peak", "r * 3", "/s"), ("Generated tokens per second at peak (500 per answer)", "t = r * 3 * 500", "/s"),
                  ("GPUs at ~2,000 tokens/s each (batched)", "t / 2000", "", "thousands of GPUs: cost per token drives every decision")]),
  SEQ("One chat turn", ["Client", "Gateway", "Orchestrator", "Safety", "Vector DB", "Inference (GPU)", "Conversation store"],
      [["Client", "Gateway", "POST /chat (SSE)"], ["Gateway", "Gateway", "auth, rate limit, token quota for the plan"], ["Gateway", "Orchestrator", "forward"],
       ["Orchestrator", "Conversation store", "save user message; load recent history", "", "Long histories are truncated or summarised to fit the context window."],
       ["Orchestrator", "Vector DB", "retrieve top-k chunks (if files/RAG)"], ["Orchestrator", "Safety", "input check"],
       ["Orchestrator", "Inference (GPU)", "enqueue (priority by plan)", "", "Continuous batching: new requests join the running batch between token steps; a shared system prompt reuses its cached KV."],
       ["Inference (GPU)", "Client", "tokens streamed (via orchestrator)", "r", "If the client disconnects, generation is cancelled to free the GPU."],
       ["Orchestrator", "Conversation store", "save assistant message + token usage"]]),
  TABLE("Levers on GPU cost and latency", ["Lever", "Effect"], [["continuous batching", "2–10× throughput vs one request at a time"], ["prefix / KV cache reuse", "skip recomputing shared system prompts"],
        ["quantisation (8/4-bit)", "more requests per GPU, small quality cost"], ["model routing", "small model for easy requests, big model when needed"], ["admission control", "shed or downgrade free tier first under overload"],
        ["speculative decoding", "a small draft model proposes tokens, the big one verifies"]]))

X("gfs-hld",
  P("""**What the system does.** A file system for huge files (GBs–TBs) spread across thousands of commodity disks, optimised for **big sequential reads and appends** (MapReduce, logs). Google's GFS / Hadoop HDFS: one **master** holds all metadata in RAM; **chunk servers** hold 64 MB chunks, each replicated 3×. Clients get locations from the master but move data **directly** with chunk servers."""),
  AN("A library where one librarian (master) knows which shelf in which building holds every chapter, but never carries books. You ask where chapters 4–6 are, then walk to those shelves yourself. Each chapter exists in three buildings."),
  CALC("Sizing", [("Data", "d = 10e15", "B"), ("Chunks of 64 MB", "c = d / 64e6", ""), ("Replicas", "c * 3", ""), ("Master RAM for metadata (~64 B per chunk)", "c * 64", "B", "why a single master works")]),
  SEQ("Write (append) with a lease", ["Client", "Master", "Primary replica", "Secondary 1", "Secondary 2"],
      [["Client", "Master", "chunk locations for file F, chunk 7?"], ["Master", "Client", "primary = CS1 (lease 60 s), secondaries CS2, CS3", "r", "The lease means only one replica orders writes for this chunk."],
       ["Client", "Primary replica", "push data (pipelined)"], ["Primary replica", "Secondary 1", "forward data"], ["Secondary 1", "Secondary 2", "forward data", "", "Data flows along a chain to use each machine's full network bandwidth."],
       ["Client", "Primary replica", "write request"], ["Primary replica", "Secondary 1", "apply in serial order #17"], ["Primary replica", "Secondary 2", "apply #17"],
       ["Primary replica", "Client", "success (all replicas applied)", "r"]]),
  TABLE("Design choices", ["Choice", "Reason", "Cost"], [["single master in RAM", "simple, globally consistent placement decisions", "bottleneck at huge scale (fixed later by Colossus / HDFS Federation)"],
        ["64 MB chunks", "few metadata entries, long sequential I/O", "small files waste chunk slots"], ["3 replicas, rack-aware", "survives disk, machine and rack loss", "3× storage"],
        ["checksums per 64 KB block", "detect silent corruption", "a little CPU"], ["operation log + checkpoints, shadow master", "master recovery", "failover not instant"]]))

X("reddit-hld",
  P("""**What the system does.** Users post links/text into communities, comment in nested threads, and vote; pages are ranked by **'hot'** (votes balanced against age). Reads (front pages) vastly outnumber writes and are cacheable; votes arrive at ~12k/s and must be **one per user per item**. Rankings are **precomputed** into sorted sets rather than calculated on every page view."""),
  AN("A notice board where people pin notes and others add ticks. Every few seconds a clerk re-sorts the board by 'ticks, discounted for age' and photographs it; visitors look at the photograph (cached ranked list), not the messy board."),
  CALC("Sizing", [("Votes per second", "1e9 / 86400", "/s"), ("Front-page reads", "50e3", "/s", "mostly CDN/Redis"), ("Vote rows per year (~24 B)", "1e9 * 365 * 24", "B")]),
  TABLE("Ranking formulas", ["Site", "Score", "Effect"], [["Reddit hot", "sign(s) · log10(max(|s|, 1)) + (age_seconds / 45,000)", "10 votes = 1 point; 12.5 h newer = 1 point; log means the first votes matter most"],
                                                         ["Hacker News", "(points − 1) / (age_hours + 2)^1.8", "gravity pulls old posts down quickly"]]),
  SEQ("A vote", ["User", "Vote service", "Votes store", "Kafka", "Ranking worker", "Ranked lists (Redis)"],
      [["User", "Vote service", "upvote post 9"], ["Vote service", "Votes store", "UPSERT (user, post 9) = +1", "", "Primary key (user, item) makes votes idempotent and lets users change their vote."],
       ["Vote service", "Kafka", "VoteChanged(post 9, delta +1)", "a"], ["Ranking worker", "Kafka", "consume (batched per post)"],
       ["Ranking worker", "Ranked lists (Redis)", "ZADD r/india:hot newScore post9", "", "Recompute only posts that changed; old posts drop out as fresher ones outscore them."]]),
  ER("Comments as a materialised path", [("comments", "PostgreSQL (sharded by post)", [("id", "bigint", "PK"), ("post_id", "bigint", "IDX"), ("parent_id", "bigint", ""), ("path", "'0001.0007.0003'", "IDX"), ("body", "text", ""), ("score", "int", "")],
                                          "WHERE post_id = 9 ORDER BY path returns a whole thread in display order with one query.")]))

X("newsagg-hld",
  P("""**What the system does.** Pulls articles from ~100k publishers, groups articles about the same event into **stories** (clusters), and shows each reader a fresh, diverse, personalised front page. The core techniques are **near-duplicate detection** and **streaming clustering with embeddings**."""),
  AN("A newspaper editor's desk: wire stories arrive all day; the editor puts reports about the same event into one folder (cluster), picks the best headline for the front page, and makes sure the page isn't five versions of the same story from the same outlet."),
  CALC("Sizing", [("New articles per second", "2e6 / 86400", "/s"), ("Source polls per second (100k sources every 5 min)", "100e3 / 300", "/s"), ("Embeddings for 30 days (768 floats × 4 B)", "2e6 * 30 * 768 * 4", "B")]),
  SEQ("An article becomes part of a story", ["Publisher", "Fetcher", "Dedup", "Clustering", "Clusters store", "Feed service"],
      [["Fetcher", "Publisher", "poll RSS / sitemap (or receive push)"], ["Fetcher", "Dedup", "extracted text + metadata"],
       ["Dedup", "Clustering", "not a near-duplicate (SimHash distance > 3)", "", "Syndicated copies of the same wire story are dropped or attached to the original."],
       ["Clustering", "Clustering", "embed; find nearest cluster centroid (ANN search)", "", "Similarity above a threshold → join that story; otherwise start a new story."],
       ["Clustering", "Clusters store", "update cluster (articles, centroid, top sources)"], ["Feed service", "Clusters store", "fresh clusters by region/topic → rank → diversify"]]),
  TABLE("Ranking the front page", ["Signal", "Why"], [["freshness", "news decays within hours"], ["cluster size / velocity", "many outlets covering it = important"], ["source authority", "trustworthy outlets first"],
                                                     ["personal interests", "topics the reader engages with"], ["diversity", "different sources and viewpoints per story"]]))

X("wallet-hld",
  P("""**What the system does.** A UPI/wallet app: send money to a phone number or QR code, pay merchants, see history. Money moves through the bank network (NPCI UPI switch and partner banks), which can be **slow or return no answer at all**. The design must never double-debit, never lose track of a payment in limbo, and always reconcile to the bank's records."""),
  AN("Sending a registered letter through a postal network you don't control: you number it (idempotency key), note its status in your own register (state machine), never post a second copy just because tracking is slow (query status instead), and every evening compare your register with the post office's (reconciliation)."),
  CALC("Sizing", [("Transactions per second (average)", "50e6 / 86400", "/s"), ("Peak (festival, salary day)", "10e3", "/s"), ("Ledger rows per year (2 entries per txn)", "50e6 * 2 * 365", "")]),
  STATE("UPI transaction states", [["INITIATED"], ["PENDING", "FAILED"], ["SUCCESS"], ["REVERSED"]],
        [["INITIATED", "PENDING", "sent to bank / NPCI"], ["INITIATED", "FAILED", "risk block"], ["PENDING", "SUCCESS", "callback / status check"], ["PENDING", "FAILED", "declined / timeout confirmed"], ["SUCCESS", "REVERSED", "dispute / refund"]]),
  SEQ("Paying ₹250 to a shop's QR", ["App", "Payment orchestrator", "Risk", "Ledger DB", "NPCI / banks"],
      [["App", "Payment orchestrator", "pay ₹250 to merchant@upi (idemKey, device-bound token)", "", "The UPI PIN is entered in the bank's secure library and never reaches our servers."],
       ["Payment orchestrator", "Ledger DB", "INSERT txn INITIATED (unique idemKey)"], ["Payment orchestrator", "Risk", "score (device, velocity, merchant)"],
       ["Payment orchestrator", "NPCI / banks", "collect/pay request (our txn id)"], ["NPCI / banks", "Payment orchestrator", "… no response in 30 s", "r", "Do NOT retry the payment. Mark PENDING and call the status-check API."],
       ["NPCI / banks", "Payment orchestrator", "callback: SUCCESS (RRN 4321…)"], ["Payment orchestrator", "Ledger DB", "PENDING → SUCCESS + balanced ledger entries (one transaction)", "", "The outbox row for 'PaymentSucceeded' is written in the same transaction, then published to Kafka."],
       ["Payment orchestrator", "App", "✔ ₹250 paid", "r"]]),
  TABLE("Hard parts", ["Problem", "Solution"], [["unknown outcome", "status-check API + T+1 reconciliation files; never blind retries"], ["hot merchant account", "split into sub-accounts and aggregate later"],
        ["history at scale", "read model built from events in a NoSQL store"], ["fraud", "device binding, velocity limits, ML scores before sending"], ["regulation", "payment data stored in India (RBI data localisation)"]]))

X("auction-hld",
  P("""**What the system does.** Sellers list items with an end time; bidders place increasing bids; the highest valid bid at the end wins. Most auctions are quiet, but popular ones get **thousands of bids in the last minute**, all racing to change the same 'current price'. Funnelling all bids for one auction to **one ordered stream and one writer** removes the race."""),
  AN("An auctioneer who only takes bids written on slips passed through one window, in the order they arrive. Each slip is checked against the current price; late slips after the hammer falls are ignored."),
  CALC("Sizing", [("Bids per second (average)", "100e6 / 86400", "/s"), ("Hot auction, last minute", "3000 / 60", "/s", "per auction: easy for a single writer")]),
  SEQ("Two bids race for one auction", ["Bidder A", "Bidder B", "Bid API", "Kafka partition (auction 55)", "Bid processor", "Auctions DB", "Watchers (WebSocket)"],
      [["Bidder A", "Bid API", "bid ₹1,050"], ["Bidder B", "Bid API", "bid ₹1,050"], ["Bid API", "Kafka partition (auction 55)", "append A, then B (key = auction id)", "a", "Same key → same partition → one total order for this auction."],
       ["Bid processor", "Kafka partition (auction 55)", "consume in order"], ["Bid processor", "Auctions DB", "A: 1,050 ≥ 1,000 + increment 50 and before end → accept; price = 1,050, leader = A"],
       ["Bid processor", "Bid processor", "B: 1,050 < 1,050 + 50 → reject (outbid)", "", "No locks: only this processor ever writes auction 55."],
       ["Bid processor", "Watchers (WebSocket)", "new price ₹1,050, leader A", "a"]]),
  TABLE("Extras", ["Feature", "Design"], [["proxy bidding", "store each bidder's maximum; the processor auto-bids the minimum needed on their behalf"], ["closing", "scheduler emits a Close event into the same partition; bids after it are rejected"],
                                        ["time", "server receive time / sequence, never client clocks"], ["anti-sniping", "optional: extend end time by 2 min if a bid arrives in the last 2 min"], ["fraud", "shill-bidding detection on bidder–seller relationships"]]))

X("calendar-hld",
  P("""**What the system does.** Create events (often **recurring**: 'every Tuesday 10:00 IST'), invite attendees who RSVP, find a time when everyone is free, and send reminders on time. Two famously tricky parts: **recurrence with time zones and DST**, and **free/busy search** across many calendars."""),
  AN("A recurring event is a rule, not a list: 'every Tuesday at 10 in Kolkata time'. You only write down exceptions ('the 24th is moved to 11'). To show next month, you expand the rule into concrete dates, in the event's own time zone so daylight-saving changes in other countries don't shift it."),
  ER("Data model", [("events", "Spanner / sharded SQL (by owner)", [("event_id", "", "PK"), ("calendar_id", "", "IDX"), ("start_local, end_local", "datetime", ""), ("tz", "'Asia/Kolkata'", ""), ("rrule", "FREQ=WEEKLY;BYDAY=TU", ""), ("exdates / overrides", "list", "")], ""),
                    ("attendees", "SQL", [("event_id", "", "PK"), ("user_id", "", "PK"), ("rsvp", "yes/no/maybe", "")], ""), ("instances", "cache", [("calendar_id", "", "PK"), ("start_utc", "", "PK"), ("event_id", "", "")], "Expanded for the next months for fast range queries.")]),
  TABLE("Free/busy: find a 30-min slot for Asha and Ravi between 10:00 and 13:00", ["Step", "Intervals"],
        [["Asha busy", "10:00–10:30, 11:00–12:00"], ["Ravi busy", "10:15–10:45, 12:30–13:00"], ["merge (sort by start, join overlaps)", "10:00–10:45, 11:00–12:00, 12:30–13:00"],
         ["gaps", "10:45–11:00 (15 min ✘), 12:00–12:30 (30 min ✔)"], ["answer", "**12:00–12:30**"]], "The classic 'merge intervals' + 'meeting rooms' algorithm: O(n log n)."),
  SEQ("Creating a meeting with reminders", ["Organiser", "Event service", "Free/busy", "Notifications", "Reminder scheduler"],
      [["Organiser", "Free/busy", "suggest times for [asha, ravi], 30 min"], ["Free/busy", "Organiser", "12:00–12:30", "r"], ["Organiser", "Event service", "create event + attendees"],
       ["Event service", "Notifications", "invites (email iCal + push)", "a"], ["Event service", "Reminder scheduler", "schedule reminder at 11:50 (time-bucketed)", "", "Buckets per minute; jitter spreads the :00 and :30 spikes."]]))

X("cdn-hld",
  P("""**What the system does.** Caches customers' content (images, video, JS) in **points of presence (PoPs)** close to users, so most requests never travel to the origin. Three questions: **routing** users to a nearby healthy PoP, **caching** efficiently inside and across PoPs, and **controlling** it all (config, purges, TLS certificates) from one place."""),
  AN("A chain of local warehouses: shoppers are sent to the nearest one; inside, each product is kept on exactly one aisle (consistent hashing) so space isn't wasted on duplicates; if the local warehouse lacks an item, it asks the regional warehouse before bothering the factory (origin)."),
  CALC("Sizing", [("Peak egress", "e = 100e12 / 8", "B/s", "100 Tbps"), ("Per PoP (200 PoPs)", "e / 200", "B/s"), ("Origin traffic at 95% hit ratio", "e * 0.05", "B/s"), ("…at 99% hit ratio", "e * 0.01", "B/s", "every extra % of hit ratio is a big origin saving")]),
  SEQ("A request for /img/logo.png", ["User", "Anycast/DNS", "Edge PoP", "Regional tier", "Origin"],
      [["User", "Anycast/DNS", "resolve cdn.example.com"], ["Anycast/DNS", "User", "nearest healthy PoP (Chennai)", "r", "Anycast: the same IP is announced from every PoP, and internet routing picks the closest."],
       ["User", "Edge PoP", "GET /img/logo.png (TLS terminated here)"], ["Edge PoP", "Edge PoP", "hash(URL) → cache server 17 in this PoP", "", "Each object lives on one server per PoP, so the PoP's total RAM/SSD is used without duplicates."],
       ["Edge PoP", "Regional tier", "miss → ask Mumbai mid-tier"], ["Regional tier", "Origin", "miss → one fetch (request collapsing)", "", "1,000 simultaneous misses for the same object become one origin request."],
       ["Origin", "Regional tier", "200 + Cache-Control: max-age=86400", "r"], ["Edge PoP", "User", "200 (cached for next users)", "r"]]),
  TABLE("Control plane", ["Function", "How"], [["purge", "fan out to all PoPs in seconds, or avoid purges with versioned URLs (logo.v42.png)"], ["config", "pushed to every PoP; staged rollouts"],
                                             ["TLS certs", "automated issuance/renewal, stored securely at edges"], ["billing/analytics", "edge logs streamed and aggregated"]]))

X("pricealert-hld",
  P("""**What the system does.** Users set alerts like 'tell me when INFY drops below ₹1,400' or 'flight under ₹4,000'. With **50 M alerts** and **50k price updates per second**, checking every alert on every update is impossible. Keep, per instrument, the thresholds **sorted**, so one price update finds all triggered alerts with a **range query**."""),
  AN("A sorted list of tripwires per stock. When the price falls to ₹1,395, you don't test each wire; you take every wire set at ₹1,395 or above in one sweep, because the list is ordered."),
  CALC("Sizing", [("Alerts", "a = 50e6", ""), ("Average alerts per instrument (1 M instruments)", "a / 1e6", ""), ("Memory for all thresholds (~40 B each)", "a * 40", "B", "partitioned across matcher nodes"), ("Price updates", "50e3", "/s")]),
  TABLE("Per-instrument index for INFY", ["'below' alerts (TreeMap threshold → ids)", "'above' alerts"], [["₹1,450 → [a7]", "₹1,600 → [a2]"], ["₹1,420 → [a1, a9]", "₹1,650 → [a5]"], ["₹1,380 → [a4]", "₹1,700 → [a8]"]],
        "Price 1,415: 'below' alerts with threshold ≥ 1,415 fire → a7, a1, a9 (tailMap); 'above' alerts with threshold ≤ 1,415 → none (headMap). Cost O(log n + fired)."),
  SEQ("A price tick", ["Price feed", "Kafka (by instrument)", "Alert matcher", "Alerts DB", "Notification queue"],
      [["Price feed", "Kafka (by instrument)", "INFY 1,415"], ["Alert matcher", "Kafka (by instrument)", "consume (this matcher owns INFY's partition)"],
       ["Alert matcher", "Alert matcher", "range query → [a7, a1, a9]; remove them from the index"], ["Alert matcher", "Alerts DB", "UPDATE alerts SET fired = true WHERE id IN (…) AND fired = false", "", "Conditional update: a restart or duplicate tick can't send the alert twice."],
       ["Alert matcher", "Notification queue", "notify owners", "a"]]),
  KEY("Mention **hysteresis** (once fired, only re-arm after the price moves back by X%) so a price flapping around the threshold doesn't spam users, and rebuilding the in-memory index from the DB plus a change stream after a restart.", "Follow-ups"))
